sys_hub_input_scripts.script:
{"short_description":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data._3__create_flow_data.record.vars.short_description;","savedValue":""},"parent":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/return fd_data._3__create_flow_data.record.vars.parent_case;","savedValue":""},"assignment_group":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/

return fd_data._3__create_flow_data.record.vars.assignment_group;","savedValue":""},"description":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data._3__create_flow_data.record.vars.description;","savedValue":""},"priority":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data._3__create_flow_data.record.vars.priority;","savedValue":""},"assigned_to":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
return fd_data._3__create_flow_data.record.vars.assigned_to;","savedValue":""}}

{"message":{"scriptActive":true,"script":"var sysId = fd_data._14__create_record.record.sys_id;
var sd = fd_data._14__create_record.record.short_description;
var date = fd_data._14__create_record.record.sys_created_on;
var assignedTo = fd_data._14__create_record.record.assigned_to.name;
var number = fd_data._14__create_record.record.number;
var instanceURL = gs.getProperty('glide.servlet.uri');
var url = "task.do?sys_id="+sysId;
instanceURL= instanceURL.concat(url);

return 'Child Case has been created successfully</p><br><p>Case Number</p><p><a href="'+instanceURL+'" target="_blank">'+number+'</a></p><p>Short Description</p><p style="max-width: 500px;white-space: nowrap;overflow: hidden;text-overflow: ellipsis;">'+sd+'</p><p>Assigned To</p><p>'+assignedTo+'</p><p>Creation Date/Time</p><p>'+date+'</p>';
"}}

{"message":{"scriptActive":true,"script":"/*
**Access Flow/Action data using the fd_data object. Script must return a value.
**example: var shortDesc = fd_data.trigger.current.short_description;
**return shortDesc;
*/
var sysId = fd_data._7__create_record.record.sys_id;
var number = fd_data._7__create_record.record.number;
var instanceURL = gs.getProperty('glide.servlet.uri');
var url = "task.do?sys_id="+sysId;
instanceURL= instanceURL.concat(url);

return '<p>Child Case has been created successfully.</p><br><p>Case Number</p><p><a href="'+instanceURL+'" target="_blank">'+number+'</a></p>';"}}

